Bash {"command":"# Try with node to parse the swagger
node -e "
const fs = require('fs');
const spec = JSON.parse(fs.readFileSync('/tmp/jitaspace/packages/esi-client/swagger.json', 'utf-8'));
const paths = Object.keys(spec.paths || {});
console.log('Total paths:', paths.length);
console.log('First 20 paths:');
paths.slice(0, 20).forEach(p => console.log('  ' + p));
console.log('...');
// Show one example operation
const firstPath = paths[0];
const methods = spec.paths[firstPath];
console.log('\nExample operation at ' + firstPath + ':');
for (const [method, op] of Object.entries(methods)) {
    console.log('  ' + method.toUpperCase() + ':');
    console.log('    operationId:', op.operationId);
    console.log('    x-rate-limit:', JSON.stringify(op['x-rate-limit']));
    console.log('    tags:', JSON.stringify(op.tags));
}
// Count schemas
const schemas = Object.keys(spec.components?.schemas || {});
console.log('\nTotal schemas:', schemas.length);
console.log('First 15 schemas:');
schemas.slice(0, 15).forEach(s => console.log('  ' + s));
""}

